# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  it "reads unsent rows above a position in ascending order up to the limit and hides only the positions marked sent" do
    insert_row = lambda do |entry_id, version|
      OutboxSnapshot.insert_all!([{
        "id" => entry_id, "project_id" => 5, "user_id" => 6, "work_date" => Date.new(2026, 3, 2), "duration" => 60.0,
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
        "source_metadata" => {}, "proof_metadata" => {}, "created_at" => Time.utc(2026, 3, 2),
        "updated_at" => Time.utc(2026, 3, 2), "company_id" => 1, "version" => version, "generation" => 1
      }], returning: %w[outbox_position]).first.fetch("outbox_position")
    end
    first = insert_row.call(77, 1)
    second = insert_row.call(77, 2)
    third = insert_row.call(78, 1)
    fourth = insert_row.call(79, 1)
    source = described_class.new
    positions = ->(rows) { rows.map { |row| row.fetch("outbox_position") } }

    expect(positions.call(source.unsent_after(0, 10))).to eq([first, second, third, fourth])
    expect(positions.call(source.unsent_after(first, 2))).to eq([second, third])

    source.mark_sent([first, third])
    # Entry 77 has a later unsent generation at the second position; marking by
    # position must leave it waiting.
    expect(positions.call(source.unsent_after(0, 10))).to eq([second, fourth])

    expect { source.mark_sent([first]) }.not_to raise_error
    expect(positions.call(source.unsent_after(0, 10))).to eq([second, fourth])
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::RelayOutboxSource do
  it "offers each row as the full entry with record ids and its own company_id, and no relay bookkeeping or credential" do
    token = "service-#{SecureRandom.hex(24)}"
    row_for = lambda do |entry_id, company_id|
      {
        "id" => entry_id, "project_id" => 5, "user_id" => 6, "agent_id" => nil, "work_date" => Date.new(2026, 3, 2),
        "duration" => 60.0, "note" => "Design review", "bill_status" => "unbilled", "review_status" => "not_required",
        "locked" => false, "source" => "agent", "source_metadata" => { "run" => { "step" => 2 } },
        "proof_metadata" => { "files" => [{ "name" => "diff.txt" }] }, "created_at" => Time.utc(2026, 3, 2),
        "updated_at" => Time.utc(2026, 3, 3), "company_id" => company_id, "version" => 3, "generation" => 4
      }
    end
    OutboxSnapshot.insert_all!([row_for.call(77, 1), row_for.call(88, 2)])

    rows = with_timekeeping_env(Timekeeping::Environment::SERVICE_TOKEN => token) do
      described_class.new.unsent_after(0, 10)
    end

    # "Payloads carry the full entry row with record ids, and no names, emails or tokens"
    expect(rows.map(&:keys)).to all(match_array(%w[generation outbox_position entry]))
    expect(rows.map { |row| row.fetch("entry").keys }).to all(match_array(Timekeeping::OutboxFields::ENTRY_FIELDS))
    expect(rows.map { |row| [row.dig("entry", "id"), row.dig("entry", "company_id"), row.fetch("generation")] })
      .to eq([[77, 1, 4], [88, 2, 4]])
    expect(rows.first.dig("entry", "proof_metadata")).to eq("files" => [{ "name" => "diff.txt" }])
    serialized = JSON.generate(rows)
    expect(serialized).not_to include("enqueued_at")
    expect(serialized).not_to include("sent_at")
    expect(serialized).not_to include(token)
  end
end
